// Secret/privacy scan. Prints counts and locations only, never matched values.
// Usage: node scan.mjs <repoRoot> <fileList.txt> [--hooksrc <archive_transcript.mjs>]
import fs from "node:fs";
import path from "node:path";
import { createHash } from "node:crypto";
import { createRequire } from "node:module";

const [root, listFile] = process.argv.slice(2);
const files = fs.readFileSync(listFile, "utf8").split(/\r?\n/).filter(Boolean);

// Dev-key hash set: parsed from the repo's hook so this script holds no key material.
const hook = fs.readFileSync(path.join(root, ".claude/hooks/archive_transcript.mjs"), "utf8");
const DEV = new Set([...hook.matchAll(/"([0-9a-f]{64})"/g)].map((m) => m[1]));
if (DEV.size !== 20) throw new Error(`expected 20 dev hashes, got ${DEV.size}`);

const req = createRequire(path.join(root, "package.json"));
const { LangEn } = req("ethers");
const BIP = new Set(LangEn.wordlist().split ? [] : []);
const wl = LangEn.wordlist();
for (let i = 0; i < 2048; i++) BIP.add(wl.getWord(i));

const HEX64 = /(?<![0-9A-Fa-f])(0x)?([0-9A-Fa-f]{64})(?![0-9A-Fa-f])/g;
const DEV_PHRASE = /\btest(?:\s+test){10}\s+junk\b/gi;
const EMAIL = /[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g;
const RPC = /https?:\/\/[^\s"'`<>)]*(infura\.io|alchemy\.com|alchemyapi\.io|quiknode\.pro|ankr\.com|chainstack\.com|blastapi\.io|drpc\.org|getblock\.io|nodereal\.io|tenderly\.co)[^\s"'`<>)]*/gi;
const APIKEYS = [
  ["anthropic", /sk-ant-[A-Za-z0-9_\-]{20,}/g],
  ["openai", /\bsk-(proj-)?[A-Za-z0-9_\-]{20,}/g],
  ["github", /\b(ghp|gho|ghu|ghs|ghr)_[A-Za-z0-9]{30,}|github_pat_[A-Za-z0-9_]{20,}/g],
  ["aws", /\bAKIA[0-9A-Z]{16}\b/g],
  ["google", /\bAIza[0-9A-Za-z_\-]{35}\b/g],
  ["slack", /\bxox[baprs]-[A-Za-z0-9-]{10,}/g],
  ["generic-assign", /(api[_-]?key|apikey|secret|token|private[_-]?key)["']?\s*[:=]\s*["']?(?!\$|process\.env|<|\[|your)[A-Za-z0-9_\-]{20,}/gi],
  ["etherscan-like", /etherscan[^\n]{0,40}?\b[A-Z0-9]{34}\b/gi],
];
const PATHS = [
  ["win-users", /[A-Za-z]:[\\\/]{1,2}Users[\\\/]{1,2}([^\\\/\s"']+)/g],
  ["unix-home", /\/home\/([A-Za-z0-9._-]+)/g],
  ["mac-users", /(?<![A-Za-z:])\/Users\/([A-Za-z0-9._-]+)/g],
  ["wsl", /\/mnt\/[a-z]\/Users\/([^\/\s"']+)/g],
];

const tot = { devKey: 0, devPhrase: 0, bipRun: 0, email: 0, rpcKeyed: 0, rpcPlain: 0, api: 0, path: 0, keyCtxHex: 0 };
const users = new Set();
const out = [];
const h = (s) => createHash("sha256").update(s).digest("hex").slice(0, 8);

for (const f of files) {
  const p = path.join(root, f);
  if (!fs.existsSync(p)) { out.push(`MISSING ${f}`); continue; }
  const text = fs.readFileSync(p, "utf8");
  const lines = text.split(/\n/);
  const hits = [];
  const lineOf = (idx) => text.slice(0, idx).split("\n").length;

  for (const m of text.matchAll(HEX64)) {
    if (DEV.has(m[2].toLowerCase())) { tot.devKey++; hits.push(`devKey@L${lineOf(m.index)}`); continue; }
    const ctx = text.slice(Math.max(0, m.index - 60), m.index).toLowerCase();
    if (/priv|secret|mnemonic|seed|signer.?key|_key\s*[:=]/.test(ctx)) { tot.keyCtxHex++; hits.push(`hex64-near-key-word@L${lineOf(m.index)}`); }
  }
  for (const m of text.matchAll(DEV_PHRASE)) { tot.devPhrase++; hits.push(`devPhrase@L${lineOf(m.index)}`); }
  // BIP-39 runs: consecutive word tokens (letters only) all in the list.
  lines.forEach((ln, i) => {
    const toks = ln.toLowerCase().split(/[^a-z]+/).filter(Boolean);
    let run = 0, best = 0;
    for (const t of toks) { run = BIP.has(t) ? run + 1 : 0; best = Math.max(best, run); }
    if (best >= 12) { tot.bipRun++; hits.push(`bip39run(${best})@L${i + 1}`); }
  });
  for (const m of text.matchAll(EMAIL)) {
    const v = m[0].toLowerCase();
    if (v.endsWith("@users.noreply.github.com")) continue;
    const dom = v.split("@")[1];
    const benign = /(^|\.)example\.(com|org|net)$|^github\.com$/.test(dom) || /\.(png|jpg|svg|js|ts|json|sol)$/.test(dom);
    tot.email++; hits.push(`email${benign ? "(benign-example)" : ""}[${h(v)}]@L${lineOf(m.index)}`);
  }
  for (const m of text.matchAll(RPC)) {
    const keyed = /\/(v2|v3|rpc|ws)?\/?[A-Za-z0-9_\-]{16,}/.test(m[0].replace(/^https?:\/\/[^/]+/, ""));
    if (keyed) { tot.rpcKeyed++; hits.push(`rpcKeyed@L${lineOf(m.index)}`); } else { tot.rpcPlain++; hits.push(`rpcHostNoKey@L${lineOf(m.index)}`); }
  }
  for (const [name, re] of APIKEYS) for (const m of text.matchAll(re)) { tot.api++; hits.push(`api:${name}@L${lineOf(m.index)}`); }
  for (const [name, re] of PATHS) {
    let n = 0, first = 0;
    for (const m of text.matchAll(re)) { n++; first ||= lineOf(m.index); users.add(m[1].toLowerCase()); }
    if (n) { tot.path += n; hits.push(`path:${name} x${n} (first L${first})`); }
  }
  if (hits.length) out.push(`${f}: ${hits.join(", ")}`);
}
console.log(out.join("\n") || "(no hits)");
console.log(`\nfiles scanned: ${files.length}`);
console.log("totals:", JSON.stringify(tot));
console.log(`distinct local usernames in paths: ${users.size} (hashes: ${[...users].map(h).join(", ")})`);

