content.content:
1	// Phase 4 §§3, 10: public reads use the configured RPC; signing is wallet-only.
2	import {
3	  BrowserProvider,
4	  Contract,
5	  FetchRequest,
6	  JsonRpcProvider,
7	  keccak256,
8	  type ContractRunner,
9	} from "ethers";
10	import { abis, deployment, type Deployment } from "../config/contracts";
11	import { targetNetwork } from "../config/networks";
12	import type { Asset, AssetAccount, Roles, WalletProvider } from "../types";
13	import {
14	  address,
15	  creationArgs,
16	  payment,
17	  quantity,
18	  type CreateAssetInput,
19	} from "../utils/validation";
20	
21	export class Blockchain {
22	  constructor(
23	    readonly provider: JsonRpcProvider,
24	    readonly config: Deployment = deployment,
25	  ) {}
26	  factory(runner: ContractRunner = this.provider) {
27	    return new Contract(
28	      address(this.config.AssetFactory),
29	      abis.factory,
30	      runner,
31	    );
32	  }
33	  token(asset: Asset, runner: ContractRunner = this.provider) {
34	    return new Contract(asset.token, abis.token, runner);
35	  }
36	  sale(asset: Asset, runner: ContractRunner = this.provider) {
37	    return new Contract(asset.sale, abis.sale, runner);
38	  }
39	
40	  async ready(provider: JsonRpcProvider | BrowserProvider = this.provider) {
41	    if (!this.config.AssetFactory)
42	      throw new Error(
43	        "Contracts are not configured. Start the local blockchain and run npm run deploy:local, then restart the frontend.",
44	      );
45	    const chain = await provider.getNetwork();
46	    if (chain.chainId !== BigInt(this.config.chainId))
47	      throw new Error(
48	        "The RPC is on the wrong network. Check the wallet network and VITE_RPC_URL.",
49	      );
50	    const code = await provider.getCode(this.config.AssetFactory);
51	    if (code === "0x")
52	      throw new Error(
53	        "Factory deployment not found. The local chain may have reset. Redeploy contracts and restart the frontend.",
54	      );
55	    if (
56	      this.config.runtimeCodeHash &&
57	      keccak256(code) !== this.config.runtimeCodeHash
58	    )
59	      throw new Error(
60	        "Factory bytecode differs from this deployment. Regenerate frontend configuration.",
61	      );
62	    if (this.config.deployBlockHash) {
63	      const block = await provider.getBlock(this.config.deployBlock);
64	      if (block?.hash !== this.config.deployBlockHash)
65	        throw new Error(
66	          "Deployment belongs to an earlier blockchain session. Redeploy and restart the frontend.",
67	        );
68	    }
69	  }
70	  async roles(account: string): Promise<Roles> {
71	    await this.ready();
72	    const factory = this.factory();
73	    const [admin, issuer] = await Promise.all([
74	      factory.admin(),
75	      factory.authorisedIssuers(account),
76	    ]);
77	    return { admin: admin.toLowerCase() === account.toLowerCase(), issuer };
78	  }
79	  async issuerStatus(account: string): Promise<boolean> {
80	    await this.ready();
81	    return this.factory().authorisedIssuers(address(account));
82	  }
83	  async asset(id: string): Promise<Asset> {
84	    if (!/^\d+$/.test(id)) throw new Error("Invalid asset ID.");
85	    const a = await this.factory().getAsset(BigInt(id));
86	    const base = {
87	      id: a.assetId.toString(),
88	      name: a.name,
89	      symbol: a.symbol,
90	      description: a.description,
91	      category: Number(a.assetType),
92	      totalSupply: a.totalSupply,
93	      token: a.tokenContract,
94	      sale: a.saleContract,
95	      issuer: a.issuerAddress,
96	    };
97	    const sale = new Contract(base.sale, abis.sale, this.provider);
98	    const [price, inventory, closed, proceeds, saleEth] = await Promise.all([
99	      sale.pricePerToken(),
100	      sale.availableTokens(),
101	      sale.saleClosed(),
102	      sale.unclaimedProceeds(),
103	      this.provider.getBalance(base.sale),
104	    ]);
105	    return { ...base, price, inventory, closed, proceeds, saleEth };
106	  }
107	  async assets(): Promise<Asset[]> {
108	    await this.ready();
109	    const count: bigint = await this.factory().getAssetCount();
110	    const result: Asset[] = [];
111	    // Bound concurrent calls; do not convert token quantities or registry IDs to floats.
112	    for (let start = 0n; start < count; start += 10n) {
113	      const ids = [];
114	      for (let id = start; id < count && id < start + 10n; id++)
115	        ids.push(id.toString());
116	      result.push(...(await Promise.all(ids.map((id) => this.asset(id)))));
117	    }
118	    return result;
119	  }
120	  async account(asset: Asset, account: string): Promise<AssetAccount> {
121	    const token = this.token(asset);
122	    const [complianceRole, adminRole] = await Promise.all([
123	      token.COMPLIANCE_ROLE(),
124	      token.DEFAULT_ADMIN_ROLE(),
125	    ]);
126	    const [balance, eligible, saleEligible, allowance, compliance, tokenAdmin] =
127	      await Promise.all([
128	        token.balanceOf(account),
129	        token.isWhitelisted(account),
130	        token.isWhitelisted(asset.sale),
131	        token.allowance(account, asset.sale),
132	        token.hasRole(complianceRole, account),
133	        token.hasRole(adminRole, account),
134	      ]);
135	    return {
136	      balance,
137	      eligible,
138	      saleEligible,
139	      allowance,
140	      compliance,
141	      tokenAdmin,
142	    };
143	  }
144	  async eligibility(asset: Asset, account: string): Promise<boolean> {
145	    return this.token(asset).isWhitelisted(address(account));
146	  }
147	  async holdings(assets: Asset[], account: string) {
148	    return Promise.all(
149	      assets.map(async (asset) => {
150	        const token = this.token(asset);
151	        const [balance, eligible] = await Promise.all([
152	          token.balanceOf(account),
153	          token.isWhitelisted(account),
154	        ]);
155	        return {
156	          asset,
157	          balance: balance as bigint,
158	          eligible: eligible as boolean,
159	        };
160	      }),
161	    );
162	  }
163	  async signer(wallet: WalletProvider, expectedAccount: string) {
164	    await this.ready();
165	    const [chain, accounts] = await Promise.all([
