// Renumber Phase 6's AUD-016 to AUD-030 in prose/source files on main. Preserves line endings.
import fs from "node:fs";
import path from "node:path";
const root = process.argv[2];
const oldName = "AUD-016-signing-wallet-deployment-is-not-checked-against-t.md";
const newName = "AUD-030-signing-wallet-deployment-is-not-checked-against-t.md";
const files = [
  "CLAUDE.md", "README.md", "docs/AI_Audit_Report.md", "docs/Final_Technical_Report.md",
  "docs/ai-logs/INDEX.md", "docs/audit/changed-files.md", "docs/audit/final-audit-summary.md",
  "docs/audit/manual-review.md", "docs/audit/remediation-log.md", "docs/audit/security-findings.md",
  `docs/issues/${newName}`, "docs/issues/INDEX.md",
  "frontend/src/services/blockchain.ts", "frontend/src/test/signingDeployment.security.test.ts",
];
fs.renameSync(path.join(root, "docs/issues", oldName), path.join(root, "docs/issues", newName));
const special = {
  "CLAUDE.md": [["- AUD-016: Matching chain IDs", "- AUD-030 (numbered AUD-016 in c7cb0d1): Matching chain IDs"]],
  "README.md": [["AUD-001 to AUD-016. ", "AUD-001 to AUD-015 and AUD-030 (Phase 6; numbered AUD-016 in c7cb0d1). AUD-016 to AUD-029 are reserved, see the index. "]],
  [`docs/issues/${newName}`]: [["# AUD-016 / SEC-013:", "# AUD-030 / SEC-013:"]],
};
let total = 0;
for (const f of files) {
  const p = path.join(root, f);
  let t = fs.readFileSync(p, "utf8");
  for (const [a, b] of special[f] || []) {
    if (!t.includes(a)) throw new Error(`${f}: special pattern missing: ${a}`);
    t = t.replace(a, b);
  }
  const n = (t.match(/AUD-016/g) || []).length;
  // In CLAUDE.md and README the only remaining AUD-016 mentions are the "numbered AUD-016 in c7cb0d1" notes.
  const keep = /numbered AUD-016 in c7cb0d1|AUD-016 to AUD-029 are reserved/g;
  const marked = t.replace(keep, (m) => m.replace("AUD-016", "\u0000"));
  t = marked.replace(/AUD-016/g, "AUD-030").replace(/\u0000/g, "AUD-016");
  total += n;
  fs.writeFileSync(p, t);
  console.log(`${f}: ${n} AUD-016 mention(s) before; ${(t.match(/AUD-030/g) || []).length} AUD-030 after`);
}
console.log(`total replaced (approx): ${total}`);

