// Classify 64-hex values on "key/secret/mnemonic" lines of a file without printing them.
// Usage: node classify-hex.mjs <file> <repoRoot> <hookPath>
import fs from "node:fs";
import { execFileSync } from "node:child_process";
import { createHash } from "node:crypto";
const [file, root, hookPath] = process.argv.slice(2);
const hook = fs.readFileSync(hookPath, "utf8");
const block = hook.slice(hook.indexOf("DEV_KEY_SHA256"), hook.indexOf("]);", hook.indexOf("DEV_KEY_SHA256")));
const hashList = new Set(block.match(/[0-9a-f]{64}/g));
// Every 64-hex value that occurs anywhere in tracked files of the repo (tx/block/code hashes in evidence etc.).
const tracked = new Set();
const out = execFileSync("git", ["-C", root, "grep", "-h", "-o", "-I", "-E", "[0-9a-fA-F]{64}", "HEAD", "--", ".", ":!docs/ai-logs/raw"], { encoding: "utf8", maxBuffer: 1 << 30 });
for (const l of out.split(/\r?\n/)) { const m = l.match(/[0-9a-fA-F]{64}$/); if (m) tracked.add(m[0].toLowerCase()); }
const cats = { hookHashList: 0, sha256OfDevKey: 0, inTrackedRepoFiles: 0, other: 0 };
const otherContexts = {};
for (const line of fs.readFileSync(file, "utf8").split(/\r?\n/)) {
  if (!/priv(ate)?[_ -]?key|secret|mnemonic/i.test(line)) continue;
  for (const m of line.matchAll(/(?<![0-9A-Fa-f])(?:0x)?([0-9A-Fa-f]{64})(?![0-9A-Fa-f])/g)) {
    const h = m[1].toLowerCase();
    if (hashList.has(createHash("sha256").update(h).digest("hex"))) continue; // dev key itself: would be redacted, counted by devKey check
    if (hashList.has(h)) cats.hookHashList++;
    else if (tracked.has(h)) cats.inTrackedRepoFiles++;
    else {
      cats.other++;
      const before = line.slice(Math.max(0, m.index - 40), m.index).replace(/[0-9A-Fa-f]{16,}/g, "<hex>").replace(/[^\w :"=./-]/g, " ");
      const key = (before.match(/([A-Za-z_]+)["\s:=]*(0x)?$/) || [, "?"])[1];
      otherContexts[key] = (otherContexts[key] || 0) + 1;
    }
  }
}
console.log(cats);
console.log("context word immediately before each 'other' value:", otherContexts);

