// Resolve the Phase 6 x origin/main merge conflicts (except README). Usage: node resolve.mjs <absWorktree>
import fs from "node:fs";
import path from "node:path";
import { execFileSync } from "node:child_process";
const root = process.argv[2];
const git = (...a) => execFileSync("git", ["-C", root, ...a], { encoding: "utf8", maxBuffer: 1 << 28 });

function resolve(file, handler) {
  const p = path.join(root, file);
  const text = fs.readFileSync(p, "utf8");
  const eol = text.includes("\r\n") ? "\r\n" : "\n";
  const lines = text.split(/\r?\n/);
  const out = [];
  let hunks = 0;
  for (let i = 0; i < lines.length; i++) {
    if (!lines[i].startsWith("<<<<<<< ")) { out.push(lines[i]); continue; }
    const ours = [], theirs = [];
    let j = i + 1;
    for (; !lines[j].startsWith("======="); j++) ours.push(lines[j]);
    for (j++; !lines[j].startsWith(">>>>>>> "); j++) theirs.push(lines[j]);
    out.push(...handler(ours, theirs, hunks++));
    i = j;
  }
  const result = out.join(eol);
  if (/^(<<<<<<<|=======|>>>>>>>)( |$)/m.test(result)) throw new Error(`${file}: markers remain`);
  fs.writeFileSync(p, result);
  console.log(`${file}: ${hunks} hunk(s) resolved`);
}

// Code: keep Phase 6's full wallet-side validation and add origin/main's stricter regulated-factory precondition.
resolve("frontend/src/services/blockchain.ts", (ours, theirs) => {
  if (!theirs.some((l) => l.includes("this.config.regulatedFactory"))) throw new Error("unexpected theirs hunk");
  if (!ours.some((l) => l.includes("await this.ready(provider);"))) throw new Error("unexpected ours hunk");
  return [
    "    // Subscription/compliance work (origin/main): a regulated deployment must carry a runtime code hash,",
    "    // so the wallet-side check below always compares factory bytecode.",
    "    if (this.config.regulatedFactory && !this.config.runtimeCodeHash)",
    "      throw new Error(",
    '        "Wallet deployment does not match the configured regulated factory.",',
    "      );",
    ...ours,
  ];
});
resolve("frontend/src/components/AppLayout.tsx", (_o, theirs) => theirs);
resolve("CLAUDE.md", (ours, theirs) => [...theirs, ...ours]);
resolve("docs/issues/INDEX.md", (ours, theirs) => [...theirs, ...ours]);
resolve("docs/ai-logs/INDEX.md", (ours, theirs) => [...ours, ...theirs]);

// add/add: keep both reports as separate files, contents unchanged apart from a top note.
const ours = git("show", ":2:docs/AI_Audit_Report.md");
const theirs = git("show", ":3:docs/AI_Audit_Report.md");
const eolO = ours.includes("\r\n") ? "\r\n" : "\n";
const eolT = theirs.includes("\r\n") ? "\r\n" : "\n";
const noteO = "> **Two AI Audit Reports exist (7 November 2026).** This file is the Phase 6 report (adityamd with Codex, c7cb0d1), verified before merge by a separate Claude Code session ([verification](phase6-verification.md)). The subscription and ERC-3643-lite compliance work wrote its own eight-section report in parallel, kept unchanged as [AI_Audit_Report-subscription.md](AI_Audit_Report-subscription.md). The team must consolidate the two into one submission report.";
const noteT = "> **Two AI Audit Reports exist (7 November 2026).** This file is the subscription/compliance report from origin/main (PRs #3 and #4), kept unchanged apart from this note; it was written before Phase 6 was merged, so it says no assembled report existed. The Phase 6 report is [AI_Audit_Report.md](AI_Audit_Report.md). The team must consolidate the two into one submission report.";
const insertAfterTitle = (t, note, eol) => { const i = t.indexOf(eol); return t.slice(0, i + eol.length) + eol + note + eol + t.slice(i + eol.length); };
fs.writeFileSync(path.join(root, "docs/AI_Audit_Report.md"), insertAfterTitle(ours, noteO, eolO));
fs.writeFileSync(path.join(root, "docs/AI_Audit_Report-subscription.md"), insertAfterTitle(theirs, noteT, eolT));
console.log("docs/AI_Audit_Report.md: ours kept; theirs -> docs/AI_Audit_Report-subscription.md");

